const fakeBin = await Bun.$`mktemp -d`.text();
const fakeRofi = `${fakeBin.trim()}/rofi`;
const capturedEntries = `${fakeBin.trim()}/entries`;
await Bun.write(fakeRofi, `#!/bin/sh\ncat > "${capturedEntries}"\nexit 1\n`);
await Bun.$`chmod +x ${fakeRofi}`;
const result = await Bun.spawn(["/home/krubics/.config/hypr/scripts/wallpaper-picker.lua"], {
  env: { ...process.env, PATH: `${fakeBin.trim()}:${process.env.PATH}`, HOME: "/home/krubics" },
  stdout: "pipe",
  stderr: "pipe",
}).exited;
const entries = (await Bun.file(capturedEntries).text()).trim().split("\n");
display({ exitCode: result, entryCount: entries.length, firstEntry: entries[0], allEntriesFromPictures: entries.every((entry) => entry.startsWith("/home/krubics/Pictures/wallpapers/")) });

